'use strict';

var Linter = require( 'eslint' ).Linter;
var rule = require( './../lib' );

var linter = new Linter();
var result;
var code;

// Generate our source code:
code = [
	'/**',
	'* Beep boop.',
	'*',
	'* ## Beep',
	'*',
	'*    boop',
	'*',
	'* ## Beep',
	'*',
	'*  beep',
	'*',
	'* @param {string} str - input value',
	'* @returns {string} output value',
	'*',
	'* @example',
	'* var out = beep( "boop" );',
	'* // returns "beepboop"',
	'*/',
	'function beep( str ) {',
	'\treturn "beep" + str;',
	'}'
].join( '\n' );

// Lint the code:
result = linter.verify( code, {
	'plugins': {
		'stdlib': {
			'rules': {
				'jsdoc-no-paragraph-content-indent': rule
			}
		}
	},
	'rules': {
		'stdlib/jsdoc-no-paragraph-content-indent': 'error'
	}
});
console.log( result );
